public sealed class ExpenseReport : AggregateRoot<ExpenseReport, Guid>
{
    private readonly List<LineItem> _lineItems = new();
    private readonly List<Approval> _approvals = new();
    private readonly List<DomainEvent> _events = new();

    public Guid EmployeeId { get; private set; }
    public Guid OrganizationId { get; private set; }
    public ReportStatus Status { get; private set; } = ReportStatus.Draft;
    public Money TotalAmount => _lineItems
        .Select(li => li.Amount)
        .Aggregate((a, b) => a + b);
    public DateTimeOffset? SubmittedAt { get; private set; }
    public IReadOnlyList<LineItem> LineItems => _lineItems.AsReadOnly();

    public void AddLineItem(LineItem item)
    {
        if (Status != ReportStatus.Draft)
            throw new DomainException("Cannot modify a submitted report.");
        if (_lineItems.Any(li => li.Category == item.Category && li.Date == item.Date))
            throw new DomainException("Duplicate line items are not allowed.");
        _lineItems.Add(item);
    }

    public void Submit(IPolicyEngine policy)
    {
        if (!_lineItems.Any())
            throw new DomainException("A report must contain at least one line item.");
        if (TotalAmount <= Money.Zero)
            throw new DomainException("Total amount must be positive.");
        policy.Validate(this);
        Status = ReportStatus.Submitted;
        SubmittedAt = DateTimeOffset.UtcNow;
        AddDomainEvent(new ExpenseReportSubmitted(this));
    }

    public void Approve(Guid approverId)
    {
        if (Status != ReportStatus.Submitted)
            throw new DomainException("Only submitted reports can be approved.");
        Status = ReportStatus.Approved;
        AddDomainEvent(new ExpenseReportApproved(Id, approverId));
    }

    public void Reject(Guid approverId, string reason)
    {
        if (Status != ReportStatus.Submitted)
            throw new DomainException("Only submitted reports can be rejected.");
        if (string.IsNullOrWhiteSpace(reason))
            throw new DomainException("A rejection reason is required.");
        Status = ReportStatus.Rejected;
        AddDomainEvent(new ExpenseReportRejected(Id, approverId, reason));
    }
}

public sealed record Money(decimal Amount, string Currency)
{
    public static Money Zero(string currency) => new(0m, currency);

    public static Money operator +(Money a, Money b)
    {
        if (a.Currency != b.Currency)
            throw new DomainException("Cannot add Money with different currencies.");
        return new Money(a.Amount + b.Amount, a.Currency);
    }

    public static bool operator >(Money a, Money b)
    {
        if (a.Currency != b.Currency)
            throw new DomainException("Cannot compare Money with different currencies.");
        return a.Amount > b.Amount;
    }

    public static bool operator <(Money a, Money b)
    {
        if (a.Currency != b.Currency)
            throw new DomainException("Cannot compare Money with different currencies.");
        return a.Amount < b.Amount;
    }
}
